// Attach to Android, then run with playwright-cli run-code --filename this file.
async page => {
    // A 4096-element ReLU graph, generated by reluModel([1, 4096]).
    const model = "";
    await page.evaluate(async model => {
        const input = Array.from({ length: 4096 }, (_, i) => Math.fround((i - 2048) / 7));
        const id = crypto.randomUUID();
        // Exercise either arrival order: the waiter can precede the native call.
        const pending = fetch('/__rank_ml_result?id=' + id).then(response => response.json());
        await window.Capacitor.nativePromise('RamGpu', 'submit', { id, payload: JSON.stringify({ model, input }) });
        const result = await pending;
        if (result.error) throw Error(result.error);
        if (result.output.length !== input.length || result.output.some((value, i) => value !== Math.max(0, input[i])))
            throw Error('Large RAM request lost or changed tensor values');
    }, model);
}
